#include <bits/stdc++.h>

using namespace std;

int a[256], b[256], c[256], n, ma, mb, mc;
string p, q, r;

int main() {
      cin >> n >> p >> q >> r;
      for (char x: p) ma = max(ma, ++a[x]);
      for (char x: q) mb = max(mb, ++b[x]);
      for (char x: r) mc = max(mc, ++c[x]);
      if (n == 1 && ma == (int)p.length()) p.pop_back();
      if (n == 1 && mb == (int)q.length()) q.pop_back();
      if (n == 1 && mc == (int)r.length()) r.pop_back();
      ma = min(ma + n, (int)p.length());
      mb = min(mb + n, (int)q.length());
      mc = min(mc + n, (int)r.length());
      if (ma > mb && ma > mc) {
            puts("Kuro");
            return 0;
      }
      if (mb > ma && mb > mc) {
            puts("Shiro");
            return 0;
      }
      if (mc > ma && mc > mb) {
            puts("Katie");
            return 0;
      }
      puts("Draw");
      return 0;
}

#include <iostream>
#include <cstdio>
#include <vector>
using namespace std;

const int MAXN = 3e5;

int n, m, u, v, x, y, sub_size[MAXN + 5];
bool vis[MAXN + 5], chk_sub[MAXN + 5];
vector<int> adj[MAXN + 5];

int DFS(int u)
{
    vis[u] = true; sub_size[u] = 1;
    if (u == x)
        chk_sub[u] = true;
    else chk_sub[u] = false;
    for (int v: adj[u])
        if (!vis[v])
        {
            sub_size[u] += DFS(v);
            chk_sub[u] |= chk_sub[v];
        }
    return sub_size[u];
}

int main()
{
    scanf("%d%d%d", &n, &x, &y);
    m = n - 1;
    while (m--)
    {
        scanf("%d%d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    DFS(y);

    long long fin;
    for (int v: adj[y])
        if (chk_sub[v])
        {
            fin = sub_size[y] - sub_size[v];
            break;
        }

    printf("%I64d", 1LL * n * (n - 1) - fin * sub_size[x]);
    return 0;
}

#include <iostream>
#include <cstdio>
#include <vector>
using namespace std;

const int MAX = 1E5 + 5;

struct SNode
{
    int mi;
    SNode *bit[2];

    SNode()
    {
        mi = MAX;
        bit[0] = bit[1] = nullptr;
    }
} *rt[MAX];
vector<int> di[MAX];
int q, t, u, k, x, s;
bool chk[MAX];

void init()
{
    for (int i = 1; i < MAX; i++)
    {
        for (int j = i; j < MAX; j += i)
            di[j].push_back(i);
        rt[i] = new SNode();
    }
}

void add(int k, int u)
{
    SNode *cur = rt[k];
    cur->mi = min(cur->mi, u);
    for (int i = 18; i >= 0; i--)
    {
        if (cur->bit[u >> i & 1] == nullptr)
            cur->bit[u >> i & 1] = new SNode();
        cur = cur->bit[u >> i & 1];
        cur->mi = min(cur->mi, u);
    }
}

int que(int x, int k, int s)
{
    SNode *cur = rt[k];
    if (x % k != 0 || cur->mi + x > s)
        return -1;
    int ret = 0;
    for (int i = 18; i >= 0; i--)
    {
        int bi = x >> i & 1;
        if (cur->bit[bi ^ 1] != nullptr && cur->bit[bi ^ 1]->mi + x <= s)
        {
            ret += ((bi ^ 1) << i);
            cur = cur->bit[bi ^ 1];
        }
        else
        {
            ret += (bi << i);
            cur = cur->bit[bi];
        }
    }
    return ret;
}

int main()
{
    init();
    scanf("%d", &q);
    while (q--)
    {
        scanf("%d", &t);
        if (t == 1)
        {
            scanf("%d", &u);
            if (!chk[u])
            {
                chk[u] = true;
                for (int k : di[u])
                    add(k, u);
            }
        }
        else
        {
            scanf("%d%d%d", &x, &k, &s);
            printf("%d\n", que(x, k, s));
        }
    }
    return 0;
}

#include <iostream>
using namespace std;

const int N = 55, MOD = 1E9 + 7;

int n, p, c[N];
long long ans = 0, pw[N], fct[N], inv[N], od[N], ev[N], f[N][N][N][N];

long long power(int u, int p)
{
    if (p == 0)
        return 1;
    long long ret = power(u, p >> 1);
    (ret *= ret) %= MOD;
    if (p & 1)
        (ret *= u) %= MOD;
    return ret;
}

long long C(int n, int k)
{
    return fct[n] * inv[k] % MOD * inv[n - k] % MOD;
}

void init()
{
    f[0][0][0][0] = 1;
    pw[0] = 1;
    fct[0] = 1;
    for (int i = 1; i < N; i++)
    {
        pw[i] = pw[i - 1] * 2 % MOD;
        fct[i] = fct[i - 1] * i % MOD;
    }
    inv[N - 1] = power(fct[N - 1], MOD - 2);
    for (int i = N - 2; i >= 0; i--)
        inv[i] = inv[i + 1] * (i + 1) % MOD;
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j <= i; j += 2)
            (ev[i] += C(i, j)) %= MOD;
        for (int j = 1; j <= i; j += 2)
            (od[i] += C(i, j)) %= MOD;
    }
}

void find_ans(int ob, int eb, int ow, int ew, int col, long long &ret)
{
    // current node is even-white
    if (col != 0 && ew != 0)
        (ret += f[ob][eb][ow][ew - 1] * pw[ow + ew - 1 + eb] % MOD * od[ob] % MOD) %= MOD;

    // current node is odd-white
    if (col != 0 && ow != 0)
        (ret += f[ob][eb][ow - 1][ew] * pw[ow - 1 + ew + eb] % MOD * ev[ob] % MOD) %= MOD;

    // current node is even-black
    if (col != 1 && eb != 0)
        (ret += f[ob][eb - 1][ow][ew] * pw[ob + eb - 1 + ew] % MOD * od[ow] % MOD) %= MOD;

    // current node is odd-black
    if (col != 1 && ob != 0)
        (ret += f[ob - 1][eb][ow][ew] * pw[ob - 1 + eb + ew] % MOD * ev[ow] % MOD) %= MOD;
}

int main()
{
    init();
    scanf("%d%d", &n, &p);
    for (int i = 1; i <= n; i++)
        scanf("%d", c + i);
    for (int i = 1; i <= n; i++)
        for (int ob = 0; ob <= i; ob++)
            for (int eb = 0; ob + eb <= i; eb++)
                for (int ow = 0; ob + eb + ow <= i; ow++)
                {
                    int ew = i - ob - eb - ow;
                    find_ans(ob, eb, ow, ew, c[i], f[ob][eb][ow][ew]);
                    if (i == n && ((ob + ow) & 1) == p)
                        (ans += f[ob][eb][ow][ew]) %= MOD;
                }
    printf("%lld", ans);
    return 0;
}
